// Runs once during workbench startup. No polling or configuration bridge.
// CSS files are generated by the extension and applied on Reload Window.
(async () => {
  try {
    const configuration = await window.vscode.context.resolveConfiguration();
    const workspaceId = configuration.workspace?.id ?? 'empty';
    if (!/^[a-zA-Z0-9_-]{1,128}$/.test(workspaceId)) {
      throw new Error('Invalid workspace identifier');
    }

    const appendStylesheet = (filename, required) => {
      const css = new URL('./' + filename, import.meta.url);
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      // The generated CSS may have changed since the previous VS Code session.
      link.href = css.href + '?startup=' + Date.now();
      link.onerror = () => {
        link.remove();
        if (required) {
          console.warn('VS Code Wallpaper: CSS is not available yet. Reload Window after the extension generates it.');
        }
      };
      document.head.append(link);
    };

    // External layers are deliberately appended after the wallpaper stylesheet.
    // This keeps one workbench loader while allowing a theme extension to own
    // translucent surfaces without duplicating the workbench.html patch.
    appendStylesheet('vscode-wallpaper-' + workspaceId + '.css', true);
    appendStylesheet('vscode-wallpaper-layers-' + workspaceId + '.css', false);
  } catch (error) {
    console.warn('VS Code Wallpaper: could not load workspace stylesheet', error);
  }
})();
